pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Wallet} from "../src/Wallet.sol";

contract InvMutTest is Test {
    Wallet c;
    function setUp() public { c = new Wallet(); }
    function testFuzz_property(address to) public {
        vm.assume(to != address(0));
        vm.assume(to != address(c));

        address donor = makeAddr("donor");
        vm.deal(donor, 10 ether);
        vm.prank(donor);
        c.deposit{value: 10 ether}();

        address creator = makeAddr("creator");
        bool ok;
        try c.migrateTo(to) { ok = true; } catch { ok = false; }

        assertTrue(!ok || address(c).balance == 0);
    }
}
